children.input:
{
  "project_id": "8b09695d1b064a91bf41",
  "query": "select now() as checked_at, count(*) as total_connections, count(*) filter (where state='active') as active_connections, count(*) filter (where state='idle') as idle_connections, count(*) filter (where wait_event is not null) as waiting_connections from pg_stat_activity where datname = current_database();

select pid, usename, application_name, client_addr, state, wait_event_type, wait_event, now()-query_start as query_age, left(query, 200) as query from pg_stat_activity where datname = current_database() and pid <> pg_backend_pid() order by query_age desc nulls last limit 30;

select name, setting, unit from pg_settings where name in ('max_connections','reserved_connections','shared_buffers','statement_timeout','idle_in_transaction_session_timeout');"
}

